#!/usr/bin/env bash
# Generated by scripts/lwfa/lwfa.jl (scripts/lwfa/picongpu.jl). Runs inside the PIConGPU container
# with the run directory at /run-dir (PM_RUN_DIR) and the GPU bound in; 2 ranks share it.
set -euo pipefail
cd "${PM_RUN_DIR:-/run-dir}"
pm-versions > versions.toml
{
  echo "# picongpu: $PICONGPU_TAG $PICONGPU_COMMIT, backend $PIC_BACKEND"
  echo "# gpu: $(nvidia-smi --query-gpu=name,driver_version --format=csv,noheader 2>/dev/null || echo unknown)"
  echo "# cpus: $(nproc)"
  echo "# cpu model: $(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2- | sed 's/^ *//')"
  echo "# compile start: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)"
} > container.txt
rm -rf setup openPMD ./*.dat
pic-create "$PIC_EXAMPLES/Empty" setup > build.log 2>&1
cp params/*.param setup/include/picongpu/param/
    (cd setup && pic-build -j 16) >> build.log 2>&1 || { tail -n 60 build.log; exit 1; }
echo "# compile end: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> container.txt
echo "# start: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> container.txt
mpiexec -n 2 setup/bin/picongpu -d 1 2 1 -r 2 -g 128 1104 128 -s 1704 --periodic 0 0 0 -m --windowMovePoint 0.9882246376811594 --autoAdjustGrid 0 --fieldAbsorber pml --currentInterpolation none --openPMD.period 142 --openPMD.file simData --openPMD.ext h5 --openPMD.infix _%06T --openPMD.source fields_all --fields_energy.period 142 > picongpu.log 2>&1 \
  || { tail -n 60 picongpu.log; exit 1; }
echo "# end: $(date -u +%Y-%m-%dT%H:%M:%S.%NZ)" >> container.txt
